def dotproduct(a, b): #yes i stole this from here https://stackoverflow.com/questions/32669855/dot-product-of-two-lists-in-python
    return sum(i[0] * i[1] for i in zip(a, b, strict=True))

def sigmoid(x):
    return 1/(1+e**-x)

